// === Tab: near_the_light ===
let ballAmount = 300;
Ball [] balls = new Array(ballAmount);
let attractor;
let bgHue, bgSatur, bgBright;

function setup() {
  createCanvas(640, 640);
  colorMode(HSB, 360, 100, 100, 100);
  background(0);

  bgHue = 210;
  bgSatur = 50;
  bgBright = 0;

  for (i = 0; i < ballAmount; i++) {
    balls [i] = new Ball(random(5, 10), i, balls);
  }
  attractor = new Attractor(30);
}

function draw() {
  //background
  noStroke();
  fill(bgHue, bgSatur, bgBright, 35);
  rect(0, 0, width, height);

  attractor.display();

  for (i = 0; i < balls.length; i++) {
    // force はアトラクタークラスにおける引力の強さ
    // 球によって強さが違う
    let force = attractor.attract(balls[i]);

    balls[i].ballCollision();

    //repelled when close and attracted when far
    let dist = PVector.dist(balls[i].location, attractor.location); // ボールと太陽(Attractor)の距離
    if (dist < attractor.radius*5) {
      force.mult(-4);
      balls[i].applyForce(force);
    } else if (dist > attractor.radius*5) {
      balls[i].applyForce(force);
    }

    balls[i].movement();
    balls[i].boundaryCollision();
    balls[i].display();
  }
}
class Attractor {
  radius; // 質量
  G;  // 重力定数
  location;

  glow;

  constructor(_radius) {
    location = new PVector(0, 0);
    radius = _radius;
    G = 1;

    glow = loadImage("https://openprocessing.org/sketch/1610006/files/glow.png");
  }

  attract(b) {
    var force = PVector.sub(location, b.location); // direction
    let d = force.mag();  // distance
    d = constrain(d, 5.0, 25.0);  // 極端に遠い距離や近い距離の値を防ぐ
    force.normalize();  //becomes 1 (this is for direction)
    let strength = (G * radius * b.radius) / (d * d); //attraction strength
    force.mult(strength);      
    return force;
  }

  function display() {
    location = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

    pushMatrix();
    translate(location.x, location.y);
    scale(radius*0.02, radius*0.02);
    tint(60,80,80);
    image(glow, -glow.width/2, -glow.height/2);
    popMatrix();

    fill(60, 60, 80);
    ellipse(location.x, location.y, radius*2, radius*2);
  }
}

class Ball {
  radius; //mass
  location, velocity, acceleration;

  trailNum = 50;
  let xTrail = new Array(trailNum);
  let yTrail = new Array(trailNum);
  indexPosition = 0;

  maxSpeed, maxForce; //for flocking

  i_; //variable for checking collision
  Ball [] otherBalls;

  glow;

  constructor(_radius, _i_, Ball [] _otherBalls) {
    location = new PVector(random(width), random(height));
    velocity = new PVector(1, 1);
    acceleration = new PVector(0, 0);
    radius = _radius;
    maxSpeed = 5;
    maxForce = 0.05;

    i_ = _i_;
    otherBalls = _otherBalls;

    glow = loadImage("https://openprocessing.org/sketch/1610006/files/glow.png");
  }

  function ballCollision() {
    //check for collision with the other balls.
    //starts at 1 because it doesn't need to check itself
    for (j = i_ + 1; j < ballAmount; j++) {
      //the distance between each ball.
      let delta = PVector.sub(otherBalls[j].location, location);
      var dist = sqrt(sq(delta.x) + sq(delta.y));
      if (dist < (radius + otherBalls[j].radius)) {
        //let normal plane
        let normalPlane = PVector.div(delta, dist);
        //let collision plane
        let midpoint = PVector.add(location, otherBalls[j].location);
        midpoint.div(2);
        //let AWAY
        location.x = midpoint.x - radius * normalPlane.x;
        location.y = midpoint.y - radius * normalPlane.y;
        otherBalls[j].location.x = midpoint.x + otherBalls[j].radius * normalPlane.x;
        otherBalls[j].location.y = midpoint.y + otherBalls[j].radius * normalPlane.y;
        //
        let dVector = (velocity.x - otherBalls[j].velocity.x) * normalPlane.x + (velocity.y - otherBalls[j].velocity.y) * normalPlane.y;
        //
        let dVelocity = normalPlane;
        dVelocity.mult(dVector);
        //updated velocities
        //let ball will have velocity subtracted and the other added
        velocity.sub(dVelocity);
        otherBalls[j].velocity.add(dVelocity);
      }
    }
  }

  function applyForce(force) {
    let friction = new PVector(velocity.x, velocity.y); //the velocity values are used to calculate friction
     friction.normalize(); //let length of the vector becomes 1
     let c = -0.2; //friction strength
     friction.mult(c); //friction
     force.add(friction);

    let f = PVector.div(force, radius);
    acceleration.add(f);
  }

  function movement() {
    velocity.add(acceleration);
    location.add(velocity);
    acceleration.mult(0);
  }

  function boundaryCollision() {
    if (location.x < radius) {
      location.x = radius;
      velocity.x *= -1;
    }
    if (location.x > width-radius) {
      location.x = width-radius;
      velocity.x *= -1;
    }
    if (location.y < radius) {
      location.y = radius;
      velocity.y *= -1;
    }
    if (location.y > height-radius) {
      location.y = height-radius;
      velocity.y *= -1;
    }
  }

  function display() {
    noStroke();
    fill(260, bgSatur, 75, 70);
    ellipse(location.x, location.y, radius*2, radius*2);
  }
}

